"""Seating charts: students sorted by last name and split into rows."""

from typing import List, Sequence

from rosterkit.models import Student


def _validate(students: Sequence[Student], per_row: int) -> None:
    if per_row <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")


def _sort_key(student: Student) -> tuple:
    return (student.last_name.lower(), student.first_name.lower())


def _row_line(number: int, row: Sequence[Student]) -> str:
    names = " | ".join(student.display_name for student in row)
    return f"Row {number}: {names}"


# ---
def seating_rows(students: Sequence[Student], per_row: int) -> List[str]:
    """One line of text per row, students ordered by last name."""
    _validate(students, per_row)
    ordered = sorted(students, key=_sort_key)
    rows = [ordered[i:i + per_row] for i in range(0, len(ordered), per_row)]
    return [_row_line(number, row) for number, row in enumerate(rows, 1)]

